func orangesRotting(_ grid: [[Int]]) -> Int {
    var g = grid, queue: [(Int, Int)] = [], fresh = 0
    for r in g.indices { for c in g[0].indices {
        if g[r][c] == 2 { queue.append((r, c)) } else if g[r][c] == 1 { fresh += 1 }
    } }
    var minutes = 0
    while !queue.isEmpty && fresh > 0 {
        var next: [(Int, Int)] = []
        for (r, c) in queue {
            for (nr, nc) in [(r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)]
            where nr >= 0 && nr < g.count && nc >= 0 && nc < g[0].count && g[nr][nc] == 1 {
                g[nr][nc] = 2; fresh -= 1; next.append((nr, nc))
            }
        }
        queue = next; minutes += 1
    }
    return fresh == 0 ? minutes : -1
}
